{"source": "def investigate(context, acquire):
    receipts = acquire("history")

    def simulate(actions, put_mode, trigger, channel_mode):
        main = {}
        other = {}
        log = 0
        main_total = 0
        other_total = 0
        last_changes = 0
        tx_conn = None
        tx_main = {}
        tx_other = {}

        def do_put(conn, key, value):
            d = main if conn == "main" else other
            changed = 0
            if put_mode == 0:
                if key not in d:
                    d[key] = value
                    changed = 1
            elif put_mode == 1:
                d[key] = value
                changed = 1
            else:
                if key in d:
                    if d[key] != value:
                        d[key] = value
                        changed = 1
                else:
                    d[key] = value
                    changed = 1
            return changed

        def do_update(conn, key, value):
            d = main if conn == "main" else other
            changed = 0
            if key in d:
                if d[key] != value:
                    d[key] = value
                    changed = 1
            return changed

        def do_delete(conn, key):
            d = main if conn == "main" else other
            changed = 0
            if key in d:
                del d[key]
                changed = 1
            return changed

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                tx_conn = conn
                if conn == "main":
                    tx_main = dict(main)
                else:
                    tx_other = dict(other)
            elif op == "commit":
                tx_conn = None
            elif op == "rollback":
                if tx_conn == "main":
                    main = tx_main
                elif tx_conn == "other":
                    other = tx_other
                tx_conn = None
            elif op == "put":
                changed = do_put(conn, act.get("key"), act.get("value"))
                if changed and trigger:
                    log += 1
                if conn == "main":
                    main_total += changed
                else:
                    other_total += changed
                last_changes = changed
            elif op == "update":
                changed = do_update(conn, act.get("key"), act.get("value"))
                if changed and trigger:
                    log += 1
                if conn == "main":
                    main_total += changed
                else:
                    other_total += changed
                last_changes = changed
            elif op == "delete":
                changed = do_delete(conn, act.get("key"))
                if conn == "main":
                    main_total += changed
                else:
                    other_total += changed
                last_changes = changed

        if channel_mode == 0:
            ch = last_changes
        elif channel_mode == 1:
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(main), sum(main.values())

    candidates = []
    for put_mode in range(3):
        for trigger in (False, True):
            for channel_mode in range(3):
                ok = True
                for r in receipts:
                    ch, cnt, sm = simulate(r["actions"], put_mode, trigger, channel_mode)
                    obs = r["observed"]
                    if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = []
    for put_mode, trigger, channel_mode in candidates:
        ch, cnt, sm = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            results.append(ch)
        elif goal == "committed_count":
            results.append(cnt)
        elif goal == "committed_sum":
            results.append(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(set(results)) == 1:
        return {"value": results[0], "unresolved": False}
    return {"value": None, "unresolved": True}
"
, "scope": "Infers put conflict mode, trigger presence, and channel counter from calibration receipts; predicts channel, committed_count, or committed_sum for new sequences.", "lesson": "The channel is a native SQLite counter, not net committed effects; rollback and conflict handling change which counter increments. Multiple family members may agree on a goal, so only return a value when all consistent candidates predict the same result."}
